def resolve(path, cwd, links):
    symlinks_followed = 0
    max_symlinks = 8

    # Determine starting position
    if path.startswith('/'):
        components = [c for c in path[1:].split('/') if c]
    else:
        # Relative path - start from cwd
        if cwd == '/':
            components = [c for c in path.split('/') if c]
        else:
            cwd_components = [c for c in cwd.split('/') if c]
            components = cwd_components + [c for c in path.split('/') if c]

    # Process components
    result = []

    while components:
        comp = components.pop(0)

        # Skip empty and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if result:
                result.pop()
            continue

        # Regular component - append it
        result.append(comp)

        # Build current path to check for symlink
        current_path = '/' + '/'.join(result)

        # Check if it's a symlink
        if current_path in links:
            symlinks_followed += 1
            if symlinks_followed > max_symlinks:
                return None

            # Get target and resolve it
            target = links[current_path]

            # Parse target into components
            if target.startswith('/'):
                # Absolute target - reset result
                target_components = [c for c in target[1:].split('/') if c]
                result = []
            else:
                # Relative target - relative to directory containing symlink
                target_components = [c for c in target.split('/') if c]
                result.pop()  # Remove the symlink name

            # Insert target components at front for processing
            components = target_components + components

    # Build final path
    if result:
        return '/' + '/'.join(result)
    else:
        return '/'

